// ===== TREND RESEARCH ORCHESTRATOR =====

const staticData = $getWorkflowStaticData('global');
const niche = staticData.niche || 'general';

const trendSources = [
  // Google Trends
  {
    platform: 'google_trends',
    url: `https://trends.google.com/trends/explore?q=${encodeURIComponent(niche)}&date=now 7-d`,
    tasks: ['Check rising queries', 'Check related topics', 'Check interest over time']
  },
  // TikTok Trending
  {
    platform: 'tiktok',
    url: `https://www.tiktok.com/search?q=${encodeURIComponent(niche + ' trending')}`,
    tasks: ['Find trending sounds', 'Find trending hashtags', 'Find trending formats']
  },
  // Instagram Explore
  {
    platform: 'instagram',
    url: `https://www.instagram.com/explore/`,
    tasks: ['Check trending reels', 'Check trending topics', 'Note viral content styles']
  },
  // Twitter/X Trending
  {
    platform: 'twitter',
    url: `https://twitter.com/explore`,
    tasks: ['Check trending topics', 'Find viral tweets in niche']
  },
  // Reddit Hot
  {
    platform: 'reddit',
    url: `https://www.reddit.com/r/${niche.replace(/\s+/g, '')}/hot/`,
    tasks: ['Check hot posts', 'Note engagement patterns']
  }
];

return [{
  json: {
    niche,
    trendSources,
    chatId: staticData.chatId
  }
}];

// ===== TREND ANALYSIS & ALERTS =====

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');

// Initialize trend data
if (!staticData.trends) {
  staticData.trends = {
    current: [],
    history: [],
    alerts: [],
    jackingOpportunities: []
  };
}

const trends = staticData.trends;

// Analyze collected trend data
const trendAnalysis = {
  hotTopics: [],
  risingQueries: [],
  viralSounds: [],
  trendingHashtags: [],
  contentFormats: [],
  jackingOpportunities: []
};

// Process each trend source
for (const source of input.trendData || []) {
  if (source.platform === 'google_trends') {
    if (source.risingQueries) trendAnalysis.risingQueries.push(...source.risingQueries);
    if (source.relatedTopics) trendAnalysis.hotTopics.push(...source.relatedTopics);
  }

  if (source.platform === 'tiktok') {
    if (source.trendingSounds) trendAnalysis.viralSounds.push(...source.trendingSounds);
    if (source.trendingHashtags) trendAnalysis.trendingHashtags.push(...source.trendingHashtags);
    if (source.trendingFormats) trendAnalysis.contentFormats.push(...source.trendingFormats);
  }

  if (source.platform === 'instagram') {
    if (source.trendingReels) trendAnalysis.contentFormats.push(...source.trendingReels);
    if (source.trendingTopics) trendAnalysis.hotTopics.push(...source.trendingTopics);
  }

  if (source.platform === 'twitter') {
    if (source.trending) trendAnalysis.hotTopics.push(...source.trending);
  }
}

// Find trend jacking opportunities
const niche = input.niche;
for (const topic of trendAnalysis.hotTopics) {
  // Check if trend is related to niche
  const relevance = calculateRelevance(topic, niche);
  if (relevance > 0.5) {
    trendAnalysis.jackingOpportunities.push({
      trend: topic,
      relevance: relevance,
      angle: `How ${topic} relates to ${niche}`,
      urgency: relevance > 0.8 ? 'HIGH' : 'MEDIUM'
    });
  }
}

// Store trends
trends.current = trendAnalysis;
trends.history.push({
  timestamp: new Date().toISOString(),
  data: trendAnalysis
});

// Keep only last 100 history entries
if (trends.history.length > 100) {
  trends.history = trends.history.slice(-100);
}

function calculateRelevance(topic, niche) {
  // Simple relevance calculation
  const topicWords = topic.toLowerCase().split(' ');
  const nicheWords = niche.toLowerCase().split(' ');
  let matches = 0;
  for (const word of nicheWords) {
    if (topicWords.some(tw => tw.includes(word) || word.includes(tw))) matches++;
  }
  return matches / nicheWords.length;
}

return [{
  json: {
    trendAnalysis,
    trends,
    chatId: input.chatId,
    hasJackingOpps: trendAnalysis.jackingOpportunities.length > 0
  }
}];

// ===== GENERATE TREND JACKING CONTENT IDEAS =====

const input = $input.first().json;
const { trendAnalysis, chatId } = input;

const jackingIdeas = trendAnalysis.jackingOpportunities.map(opp => {
  return {
    trend: opp.trend,
    urgency: opp.urgency,
    contentIdeas: [
      `Carousel: "How ${opp.trend} connects to your niche"`,
      `Reel: Quick take on ${opp.trend}`,
      `Story: Your opinion on ${opp.trend}`,
      `Carousel: "What everyone gets wrong about ${opp.trend}"`
    ],
    hook: `"Everyone's talking about ${opp.trend}... here's what they're missing"`,
    hashtags: `#${opp.trend.replace(/\s+/g, '')} #trending #viral`,
    urgencyNote: opp.urgency === 'HIGH' ? '🚨 POST WITHIN 2 HOURS!' : '📌 Post within 24 hours'
  };
});

return [{
  json: {
    jackingIdeas,
    chatId
  }
}];

